'use strict';
const page=document.body.dataset.page;
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const photos={
 rtx5070:{file:'rtx-5070.png',model:'ASUS Prime OC',url:'https://www.asus.com/motherboards-components/graphics-cards/prime/prime-rtx5070-o12g/'},
 rtx5060ti16:{file:'rtx-5060-ti.png',model:'ASUS Dual OC 16GB',url:'https://www.asus.com/motherboards-components/graphics-cards/dual/dual-rtx5060ti-o16g/'},
 rtx4080s:{file:'rtx-4080-super.png',model:'ASUS TUF Gaming OC',url:'https://www.asus.com/us/motherboards-components/graphics-cards/tuf-gaming/tuf-rtx4080s-o16g-gaming/'},
 rx7900xtx:{file:'rx-7900-xtx.png',model:'ASUS TUF Gaming OC',url:'https://www.asus.com/motherboards-components/graphics-cards/tuf-gaming/tuf-rx7900xtx-o24g-gaming/'}
};
let toastTimer;
function announce(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function shortName(p){return p.name.replace('GeForce ','').replace('Radeon ','');}
function photo(p,cls=''){const asset=photos[p.id];return asset?`<img class="${cls}" src="/assets/${asset.file}" alt="${escapeHTML(asset.model+' '+p.name+' graphics card')}" width="1000" height="400">`:`<div class="photo-unavailable"><span>${escapeHTML(p.brand)}</span><strong>${escapeHTML(p.architecture)}</strong><small>Product photo unavailable</small></div>`;}
const themeButton=$('.theme-toggle');
function updateThemeLabel(){const dark=document.documentElement.dataset.theme==='dark';themeButton.setAttribute('aria-label',`Switch to ${dark?'light':'dark'} mode`);themeButton.title=`Switch to ${dark?'light':'dark'} mode`;$('.theme-label').textContent=dark?'Light mode':'Dark mode';}
themeButton.addEventListener('click',()=>{document.documentElement.dataset.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';try{localStorage.setItem('pcp-theme',document.documentElement.dataset.theme)}catch{}updateThemeLabel();});updateThemeLabel();
const params=new URL(location.href).searchParams;
const validIDs=list=>[...new Set(list)].filter(id=>catalog.some(p=>p.id===id)).slice(0,4);
selected=params.has('parts')?validIDs(params.get('parts').split(',')):['rtx5070','rtx5060ti16'];
if(page==='home'&&(params.has('parts')||params.has('build')||['#compare','#builder','#catalog'].includes(location.hash))){const destination=params.has('build')||location.hash==='#builder'?'builder':location.hash==='#catalog'?'hardware':'compare';location.replace('/'+destination+'/'+location.search);}
if(parts()[0])activeCategory=parts()[0].cat;
function saveComparison(){const url=new URL(location.href);url.searchParams.set('parts',selected.join(','));history.replaceState(null,'',url);try{sessionStorage.setItem('pcp-comparison',JSON.stringify(selected))}catch{}}
function imageCard(p,i){return `<article class="product-card" style="--series:${['var(--chart-a)','var(--chart-b)','#a677d2','#b9763c'][i]}"><div class="product-top"><span class="product-index">0${i+1} / ${escapeHTML(p.brand)}</span><button class="icon-button remove-product" data-remove="${p.id}" aria-label="Remove ${escapeHTML(p.name)}">×</button></div><div class="product-image">${photo(p)}</div><div class="product-heading"><span class="eyebrow">${escapeHTML(p.brand)} ${p.year?'· '+p.year:''}</span><h2>${escapeHTML(shortName(p))}</h2><p>${escapeHTML(p.summary)}</p><button class="change-product" data-replace="${i}" aria-label="Change ${escapeHTML(p.name)}">Change hardware <span aria-hidden="true">⌄</span></button></div><div class="product-meta"><span>${escapeHTML(p.architecture)}</span><span>${photos[p.id]?'Partner model shown':'Reference specs'}</span></div></article>`;}
function renderComparison(){
 const ps=parts();$('#comparison-cards').style.setProperty('--count',Math.max(ps.length,2));$('#comparison-cards').innerHTML=ps.map(imageCard).join('')+(ps.length<2?`<button class="empty-product" data-new="true"><span>＋</span><strong>Choose ${ps.length?'another':'your first'} part</strong><small>Search the hardware catalog</small></button>`:'');
 $('#add-comparison').hidden=ps.length>=4;$('#export-csv').disabled=!ps.length;
 $('#compare-categories').innerHTML=[['gpu','Graphics cards'],['cpu','Processors'],['ssd','Storage']].map(([id,label])=>`<button data-category="${id}" aria-pressed="${activeCategory===id}" class="${activeCategory===id?'active':''}">${label}</button>`).join('');
 $('#more-category').innerHTML='<option value="">More hardware</option>'+categories.filter(([id])=>!['gpu','cpu','ssd'].includes(id)).map(([id,label])=>`<option value="${id}" ${id===activeCategory?'selected':''}>${label}</option>`).join('');
 const keys=[...new Set(ps.flatMap(p=>Object.keys(p.specs)))];const preferred=activeCategory==='cpu'?['CPU cores','Boost clock','CPU TDP']:activeCategory==='ssd'?['Storage capacity','Sequential read','Sequential write']:['Memory','Memory bandwidth','Board power'];let chartKeys=preferred.filter(k=>keys.includes(k));if(!chartKeys.length)chartKeys=keys.slice(0,3);
 $('#metric-grid').innerHTML=chartKeys.map(key=>{const max=Math.max(...ps.map(p=>Number(p.specs[key])||0),1);return `<article class="metric-card"><h3>${escapeHTML(key)} <span>${units[key]||''}</span></h3>${ps.map((p,i)=>`<div class="metric-row"><div><span>${escapeHTML(shortName(p))}</span><strong>${number(p.specs[key])}</strong></div><div class="metric-track">${p.specs[key]!==undefined?`<span style="width:${Math.max(0,Number(p.specs[key])/max*100)}%;background:${['var(--chart-a)','var(--chart-b)','#a677d2','#b9763c'][i]}"></span>`:''}</div></div>`).join('')}</article>`}).join('')||'<p class="empty-message">Choose hardware to see its specifications.</p>';
 const onlyDiff=$('#differences-only').checked;const rows=keys.filter(k=>!onlyDiff||new Set(ps.map(p=>p.specs[k])).size>1);
 $('#spec-count').textContent=rows.length+' specifications';
 $('#comparison-table').innerHTML=ps.length?`<table><thead><tr><th>Specification</th>${ps.map(p=>`<th>${escapeHTML(shortName(p))}</th>`).join('')}</tr></thead><tbody>${rows.map(k=>`<tr><td>${escapeHTML(k)}</td>${ps.map(p=>`<td>${escapeHTML(value(p,k))}</td>`).join('')}</tr>`).join('')||`<tr><td colspan="${ps.length+1}">No differences in the available specifications.</td></tr>`}<tr data-metadata><td>Architecture</td>${ps.map(p=>`<td>${escapeHTML(p.architecture)}</td>`).join('')}</tr><tr data-metadata><td>Release year</td>${ps.map(p=>`<td>${p.year||'Unavailable'}</td>`).join('')}</tr></tbody></table>`:'<p class="empty-message">Your comparison is empty. Add a part to begin.</p>';
 $('#comparison-warning').innerHTML=new Set(ps.map(p=>p.cat)).size>1?'<p class="notice">You’re comparing different categories. Shared memory, dedicated VRAM and core counts are not interchangeable.</p>':'';
 $('#comparison-sources').innerHTML=ps.map(p=>`<article><strong>${escapeHTML(p.name)}</strong><p>${escapeHTML(p.note||'Reference specifications. Partner models and operating conditions may differ.')}</p><a href="${escapeHTML(p.source)}" target="_blank" rel="noopener">Specification source ↗</a>${photos[p.id]?`<a href="${photos[p.id].url}" target="_blank" rel="noopener">Photo: ${photos[p.id].model} ↗</a>`:''}</article>`).join('')+'<p>A dash means unavailable. <a href="/methodology/">How we use data →</a></p>';
 if(onlyDiff){document.querySelectorAll('#comparison-table tr[data-metadata]').forEach(row=>{if(new Set([...row.cells].slice(1).map(cell=>cell.textContent)).size<=1)row.remove();});}
 saveComparison();
}
let replacing=null,pickerCategory=null,returnFocus=null;
function openPicker(index=null,category=activeCategory){replacing=index;pickerCategory=category;returnFocus=document.activeElement;$('#picker-query').value='';$('#part-picker').showModal();renderPicker();$('#picker-query').focus();}
function closePicker(){$('#part-picker').close();returnFocus?.isConnected?returnFocus.focus():$('#add-comparison')?.focus();}
function renderPicker(){const query=$('#picker-query').value.trim().toLowerCase();const choices=catalog.filter(p=>(!pickerCategory||p.cat===pickerCategory)&&!selected.includes(p.id)&&`${p.name} ${p.brand} ${p.architecture}`.toLowerCase().includes(query)).sort((a,b)=>(b.year||0)-(a.year||0));$('#picker-results').innerHTML=choices.length?choices.slice(0,80).map(p=>`<button data-pick="${p.id}"><span><strong>${escapeHTML(p.name)}</strong><small>${escapeHTML(p.summary)} · ${p.year||'Year unavailable'}</small></span><span aria-hidden="true">＋</span></button>`).join(''):'<p class="empty-message">No matching hardware in this category. Try a shorter model name.</p>';}
$('#picker-query').addEventListener('input',renderPicker);$('#close-picker').addEventListener('click',closePicker);$('#part-picker').addEventListener('click',e=>{if(e.target===$('#part-picker')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closePicker();}});
function exportCSV(){const ps=parts(),keys=[...new Set(ps.flatMap(p=>Object.keys(p.specs)))],quote=v=>'"'+String(v??'Unavailable').replaceAll('"','""')+'"';const rows=[['Specification','Unit',...ps.map(p=>p.name)],...keys.map(k=>[k,units[k]||'',...ps.map(p=>p.specs[k])]),['Source','',...ps.map(p=>p.source)]];const url=URL.createObjectURL(new Blob(['\uFEFF'+rows.map(row=>row.map(quote).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download='hardware-comparison.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);announce('Comparison exported.');}
if(page==='compare'){
 renderComparison();$('#differences-only').addEventListener('change',renderComparison);$('#add-comparison').addEventListener('click',()=>openPicker());$('#more-category').addEventListener('change',e=>{if(e.target.value){activeCategory=e.target.value;renderComparison();openPicker(null,activeCategory);}});$('#export-csv').addEventListener('click',exportCSV);
 document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.remove){selected=selected.filter(id=>id!==b.dataset.remove);renderComparison();announce('Part removed.')}else if(b.dataset.replace!==undefined){openPicker(Number(b.dataset.replace),parts()[Number(b.dataset.replace)].cat);}else if(b.dataset.new)openPicker();else if(b.dataset.category){activeCategory=b.dataset.category;renderComparison();openPicker(null,activeCategory);}else if(b.dataset.pick){if(replacing!==null)selected[replacing]=b.dataset.pick;else if(selected.length<4)selected.push(b.dataset.pick);else{announce('Remove a part before adding another.');return;}closePicker();renderComparison();announce('Comparison updated.');}});
}
if(page==='hardware'||page==='learn'){
 try{const saved=JSON.parse(sessionStorage.getItem('pcp-comparison'));if(Array.isArray(saved))selected=validIDs(saved);}catch{}
 let limit=24;$('#catalog-category').innerHTML='<option value="all">All hardware</option>'+categories.map(([id,label])=>`<option value="${id}">${label}</option>`).join('');if(categories.some(([id])=>id===params.get('category')))$('#catalog-category').value=params.get('category');
 function renderLibrary(){const q=$('#catalog-search').value.trim().toLowerCase(),cat=$('#catalog-category').value,era=$('#catalog-era').value,sort=$('#catalog-sort').value;const rows=catalog.filter(p=>(cat==='all'||p.cat===cat)&&`${p.name} ${p.brand} ${p.architecture} ${p.summary}`.toLowerCase().includes(q)&&(era==='all'||(p.year&&(era==='modern'?p.year>=2020:p.year<2020)))).sort((a,b)=>sort==='name'?a.name.localeCompare(b.name):sort==='old'?(a.year||9999)-(b.year||9999):(b.year||0)-(a.year||0));$('#hardware-rows').innerHTML=rows.slice(0,limit).map(p=>`<tr><td><a href="/learn/${p.id}.html"><strong>${escapeHTML(p.name)}</strong><span>${escapeHTML(p.brand)} · ${escapeHTML(p.architecture)}</span></a></td><td>${escapeHTML(categories.find(c=>c[0]===p.cat)?.[1]||p.cat)}</td><td>${p.year||'—'}</td><td>${escapeHTML(p.summary)}</td><td><button class="catalog-add ${selected.includes(p.id)?'chosen':''}" data-library-add="${p.id}" aria-label="${selected.includes(p.id)?'Remove':'Compare'} ${escapeHTML(p.name)}">${selected.includes(p.id)?'✓ Added':'+ Compare'}</button></td></tr>`).join('');$('#catalog-summary').textContent=`${Math.min(rows.length,limit)} of ${rows.length.toLocaleString()} records`;$('#catalog-empty').hidden=!!rows.length;$('#catalog-more').hidden=limit>=rows.length;$('#selected-link').href='/compare/?parts='+selected.join(',');$('#selected-link').textContent=`Compare selected (${selected.length}) →`;}
 for(const id of ['catalog-search','catalog-category','catalog-era','catalog-sort'])$('#'+id).addEventListener(id==='catalog-search'?'input':'change',()=>{limit=24;renderLibrary();});$('#catalog-more').addEventListener('click',()=>{limit+=36;renderLibrary();});document.addEventListener('click',e=>{const b=e.target.closest('[data-library-add]');if(!b)return;const id=b.dataset.libraryAdd;if(selected.includes(id))selected=selected.filter(x=>x!==id);else if(selected.length<4)selected.push(id);else{announce('Four parts selected. Remove one or open your comparison.');return;}try{sessionStorage.setItem('pcp-comparison',JSON.stringify(selected));}catch{}renderLibrary();announce(`${selected.length} parts selected.`);});renderLibrary();
}
if(page==='builder'){
 if(params.has('build')){pcBuild={};const values=params.get('build').split(',');buildSlotDefs.forEach((slot,i)=>{const ids=(values[i]||'').split('~').filter(id=>catalog.some(p=>p.id===id&&p.cat===slot.id));if(ids.length)pcBuild[slot.id]=['cpu','gpu','ram','ssd','hdd'].includes(slot.id)?ids:ids[0];});}if(params.get('compat')==='all')compatibleOnly=false;
 $('#enable-incompatible').addEventListener('change',e=>{compatibleOnly=!e.target.checked;renderBuilder();});
}
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&$('#catalog-search')){e.preventDefault();$('#catalog-search').focus();}});
